export const PROFESSIONS={frontend:{name:'Разработчик',accent:'#b8a0ff',bonus:'Кейсы разработки: +15% выручки',role:'Разработчик'},security:{name:'Белый хакер',accent:'#9ce768',bonus:'Аудиты: +20% выручки, +10% силы в войне',role:'Белый хакер'},sysadmin:{name:'Сисадмин',accent:'#ffba70',bonus:'CPU/GPU: +15% мощности; сеть: +15% выручки',role:'Сисадмин'}};
const levels=['Б/У','Офис','Старт','Поток','Вектор','Импульс','Спектр','Турбо','Профи','Ультра'];
for(const cat of ['gpu','cpu'])for(let n=1;n<=29;n++){const rating=Math.round(3*Math.pow(1.14,n));CATALOG.push({id:cat+'-'+n,cat,name:(cat==='gpu'?'Видеокарта / VECTOR ':'Процессор / CORE ')+String(n).padStart(2,'0')+' · '+levels[Math.min(9,Math.floor(n/3))],icon:cat==='gpu'?'◫':'▦',base:Math.round(190*Math.pow(1.23,n)),power:rating,install:true,desc:'Учебная модель. Индекс '+rating+'. Для полной загрузки нужен '+(cat==='gpu'?'CPU':'GPU')+' с сопоставимым индексом.'});}
export const RELICS=[
 ['cache','Кэш-пакет','Обычный',30,{speed:.03},'Кейсы выполняются на 3% быстрее'],
 ['copper','Медная шина','Обычный',25,{hardware:.04},'Мощность связки CPU/GPU +4%'],
 ['green','Зелёный ключ','Редкий',12,{income:.05},'Вся выручка кейсов и вычислений +5%'],
 ['cooler','Криокулер','Редкий',10,{hardware:.08},'Мощность связки CPU/GPU +8%'],
 ['thread','Параллельный поток','Редкий',8,{speed:.08},'Скорость выполнения кейсов +8%'],
 ['shield','Щит периметра','Эпический',5,{war:.12},'Сила команды в клановой войне +12%'],
 ['tensor','Тензорное ядро','Эпический',4,{compute:.15},'Доход вычислительного кластера +15%'],
 ['architect','Печать архитектора','Эпический',3,{income:.08,speed:.04},'Вся выручка +8%, скорость кейсов +4%'],
 ['quantum','Квантовый мост','Легендарный',2,{hardware:.15,compute:.10},'Мощность CPU/GPU +15%, вычисления +10%'],
 ['founder','Ключ основателя','Легендарный',1,{income:.12,war:.08},'Вся выручка +12%, сила клана +8%']
].map(([id,name,rarity,weight,buffs,desc],i)=>({id:'relic-'+id,name,rarity,weight,buffs,desc,cat:'relic',icon:'◇',base:1500*(i+1)}));
export const THEMES=[['classic','Архитектурное бюро','#a8bbae','#283b40'],['hacker','Хакерская с миньонами','#d0ed4d','#15251b'],['arctic','Полярная станция','#8be6ff','#203344'],['sunset','Токийский закат','#ff9a7a','#443044'],['orbital','Орбитальный центр','#c2adff','#292641'],['garden','Ботанический офис','#afda8d','#344a36'],['industrial','Индустриальный цех','#f8b568','#433a31'],['ocean','Подводная лаборатория','#62dfce','#173d46']].map(([key,name,color,wall],i)=>({id:'theme-'+key,key,name,cat:'theme',icon:'⌂',base:1200+i*850,desc:'Оформление базы 2D и 3D. Без бонусов к экономике.',color,wall}));
CATALOG.push(...RELICS,...THEMES);
export function migrateTycoon(s){s.profession=PROFESSIONS[s.profession]?s.profession:null;s.activeRelics=s.activeRelics||[];s.themes=s.themes||['theme-classic'];s.theme=s.theme||'theme-classic';s.loot=s.loot||[];s.computeRevenue=s.computeRevenue||0;for(const p of CATALOG){if(s.prices[p.id]===undefined)s.prices[p.id]=p.base;if(!s.history[p.id])s.history[p.id]=Array.from({length:30},()=>({o:p.base,c:p.base,h:p.base*1.01,l:p.base*.99}));}return s;}
export function buffs(s){return (s.activeRelics||[]).reduce((a,id)=>{for(const [k,v] of Object.entries(item(id).buffs||{}))a[k]=(a[k]||0)+v;return a;},{});}
export function hardware(s){const cpu=CATALOG.filter(p=>p.cat==='cpu').reduce((n,p)=>n+(s.installed[p.id]||0)*p.power,0),gpu=CATALOG.filter(p=>p.cat==='gpu').reduce((n,p)=>n+(s.installed[p.id]||0)*p.power,0);const useful=2*Math.min(cpu,gpu),efficiency=cpu+gpu?useful/(cpu+gpu):0;return {cpu,gpu,efficiency,useful,power:useful*(1+(buffs(s).hardware||0))*(s.profession==='sysadmin'?1.15:1),bottleneck:cpu===gpu?'Баланс':cpu<gpu?'Нужен более мощный CPU':'Нужна более мощная GPU'};}
export function revenueMultiplier(s,role){return 1+bonus(s.clan?.trophies)+(buffs(s).income||0)+(role&&PROFESSIONS[s.profession]?.role===role?(s.profession==='security'?.20:.15):0);}
export function equipRelic(s,id){const p=item(id);check(p.cat==='relic'&&(s.inventory[id]||0)>0,'Предмета нет на складе');check(!s.activeRelics.includes(id),'Такой эффект уже активен');check(s.activeRelics.length<3,'Доступны три слота усилений');s.inventory[id]--;s.activeRelics.push(id);}
export function unequipRelic(s,id){check(s.activeRelics.includes(id),'Предмет не активен');s.activeRelics=s.activeRelics.filter(x=>x!==id);s.inventory[id]=(s.inventory[id]||0)+1;}
export function awardLoot(s){let roll=random(s)*100;const p=RELICS.find(p=>(roll-=p.weight)<0)||RELICS.at(-1);s.inventory[p.id]=(s.inventory[p.id]||0)+1;s.loot.unshift({id:p.id,time:s.time});s.loot=s.loot.slice(0,20);log(s,'Клановый кейс: '+p.name+' · '+p.rarity+'. '+p.desc);return p;}
export function orderBook(s,id){const q=price(s,id);return ['sell','buy'].flatMap(side=>Array.from({length:7},(_,i)=>({side,limit:money(q*(1+(side==='sell'?1:-1)*(.008+i*.004))),qty:3+Math.floor((Math.sin(s.time*.2+i*7)+1)*12),npc:true}))).concat(s.orders.filter(o=>o.id===id).map(o=>({...o,npc:false}))).sort((a,b)=>b.limit-a.limit);}
export const CASES=[{id:'landing',name:'Экстренный релиз банка',need:2,work:75,reward:700,role:'Разработчик',desc:'Восстановить поток переводов и безопасно выпустить обновление.'},{id:'network',name:'Сеть нового офиса',need:5,work:180,reward:1800,role:'Сисадмин',desc:'Подключить команду и настроить инфраструктуру.'},{id:'audit',name:'Проверка безопасности',need:9,work:340,reward:3400,role:'Белый хакер',desc:'Найти слабые места до следующей атаки.'},{id:'platform',name:'Платформа для города',need:20,work:900,reward:8200,role:'Разработчик',desc:'Большой кейс для слаженной команды.'}];
export const CATEGORIES=[['all','Все'],['people','Специалисты'],['storage','SSD'],['memory','Оперативка'],['cpu','Процессоры'],['gpu','Видеокарты'],['office','Мониторы и кресла'],['space','Площадь'],['relic','Усиления'],['theme','Темы базы']];
export const item=id=>{const p=CATALOG.find(x=>x.id===id);if(!p)throw Error('Товар не найден');return p;};
const check=(condition,message)=>{if(!condition)throw Error(message);};const money=n=>Math.round(n*100)/100;
function random(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function uid(s){return 'k'+s.nextId++;}
export function createTycoon(name='Моя компания'){return {profession:null,activeRelics:[],themes:['theme-classic'],theme:'theme-classic',loot:[],computeRevenue:0,version:1,name:String(name).slice(0,34)||'Моя компания',cash:9000,time:0,seed:912744,nextId:1,area:16,inventory:{junior:2,ssd:1,ram:1},installed:{},workers:[],jobs:[],finished:0,revenue:0,prices:Object.fromEntries(CATALOG.map(p=>[p.id,p.base])),history:Object.fromEntries(CATALOG.map(p=>[p.id,Array.from({length:30},(_,i)=>({o:p.base*(1+Math.sin(i*.6)*.025),h:p.base*1.04,l:p.base*.96,c:p.base*(1+Math.sin((i+1)*.6)*.025)}))])),marketClock:0,orders:[],positions:[],auction:null,clan:null,war:null,warReady:0,log:['Компания основана. На счету 9 000 CR. На складе два контракта Junior, SSD и RAM.'],speed:1};}
export function restoreTycoon(raw){const s=JSON.parse(raw);check(s?.version===1&&Number.isFinite(s.cash)&&s.cash>=0&&Number.isFinite(s.time)&&s.time>=0&&Number.isInteger(s.area)&&s.area>=16,'Сохранение тайкона повреждено.');for(const k of ['workers','jobs','orders','positions','log'])check(Array.isArray(s[k]),'Нет данных '+k);migrateTycoon(s);for(const p of CATALOG){check(Number.isFinite(s.prices[p.id])&&s.prices[p.id]>0,'Некорректная цена');check(Array.isArray(s.history[p.id]),'Нет истории котировок');}check(s.inventory&&s.installed&&Object.values(s.inventory).every(n=>Number.isInteger(n)&&n>=0),'Некорректный склад');return s;}
function log(s,t){s.log.unshift(t);s.log=s.log.slice(0,70);}
export function capacity(s){return Math.floor(s.area/4);}
export function equipment(s){return CATALOG.filter(p=>!['cpu','gpu'].includes(p.cat)).reduce((n,p)=>n+(s.installed[p.id]||0)*(p.power||0),0)+hardware(s).power;}
export function activeWorkers(s){return s.workers.filter(w=>w.until>s.time);}
export function bonus(trophies=0){return trophies>=10000?.25:trophies>=7000?.15:trophies>=5000?.10:trophies>=2000?.05:trophies>=1000?.01:0;}
export function power(s){return activeWorkers(s).reduce((n,w)=>n+w.skill,0)+equipment(s);}
export function price(s,id){return s.prices[id];}
export function buy(s,id,qty=1,source='nds'){const p=item(id);check(Number.isInteger(qty)&&qty>0&&qty<=1000,'Количество: от 1 до 1 000');const unit=source==='market'?price(s,id)*1.008:p.base,cost=money(unit*qty);check(s.cash>=cost,'Не хватает CR');s.cash=money(s.cash-cost);s.inventory[id]=(s.inventory[id]||0)+qty;log(s,`${source==='market'?'Рынок':'НДС'}: ${p.name} ×${qty}, −${cost} CR.`);}
export function useItem(s,id){const p=item(id);check((s.inventory[id]||0)>0,'Нет предмета на складе');if(p.skill){check(activeWorkers(s).length<capacity(s),'Нет рабочего места. Купи площадь.');check(s.cash>=p.wage,'Не хватает на оплату часа');s.cash-=p.wage;s.workers.push({id:uid(s),kind:id,name:['Алекс','Ника','Тим','Майя','Лев','Саша'][s.nextId%6]+' / '+p.name.split('/ ')[1],role:p.role,skill:p.skill,until:s.time+3600,wage:p.wage});log(s,`${p.role} принят на час. Зарплата ${p.wage} CR оплачена.`);}else if(id==='sqm'){s.area+=4;log(s,'Офис расширен: '+s.area+' м².');}else if(p.cat==='theme'){if(!s.themes.includes(id))s.themes.push(id);s.theme=id;}else if(p.cat==='relic'){equipRelic(s,id);return;}else throw Error('Установи оборудование в 3D через кнопку «Установить».');s.inventory[id]--;}
export function install(s,id){const p=item(id);check(p.install&&(s.inventory[id]||0)>0,'Оборудование недоступно');s.inventory[id]--;s.installed[id]=(s.installed[id]||0)+1;log(s,p.name+' установлен в офисе.');}
export function startCase(s,id){const p=CASES.find(c=>c.id===id);check(p,'Кейс не найден');check(activeWorkers(s).length,'Сначала активируй контракт сотрудника на складе');check(!s.jobs.some(j=>!j.done),'Команда уже выполняет кейс');check(power(s)>=p.need,'Нужно '+p.need+' мощности. Найми людей или установи оборудование.');s.jobs.push({id:uid(s),kind:id,progress:0,done:false,reward:0});log(s,'Начат кейс: '+p.name);}
export function listOrder(s,id,side,qty,limit){item(id);check(['buy','sell'].includes(side)&&Number.isInteger(qty)&&qty>0&&qty<=1000&&Number.isFinite(limit)&&limit>0,'Проверь количество и цену');limit=money(limit);if(side==='sell'){check((s.inventory[id]||0)>=qty,'Недостаточно товара');s.inventory[id]-=qty;}else{check(s.cash>=limit*qty*1.005,'Не хватает CR для резервирования');s.cash=money(s.cash-limit*qty*1.005);}s.orders.push({oid:uid(s),id,side,qty,limit});log(s,`Заявка ${side==='buy'?'на покупку':'на продажу'}: ${item(id).name}, ${qty} × ${limit} CR.`);}
export function cancelOrder(s,oid){const i=s.orders.findIndex(o=>o.oid===oid);check(i>=0,'Заявка уже исполнена');const o=s.orders[i];if(o.side==='sell')s.inventory[o.id]=(s.inventory[o.id]||0)+o.qty;else s.cash=money(s.cash+o.limit*o.qty*1.005);s.orders.splice(i,1);}
export function openPosition(s,id,side,margin,leverage){item(id);check(['long','short'].includes(side)&&Number.isFinite(margin)&&margin>=50&&[1,2,3,5,10].includes(leverage),'Проверь направление, залог и плечо');check(s.positions.length<5,'Максимум 5 открытых позиций');const fee=margin*leverage*.0006;check(s.cash>=margin+fee,'Не хватает CR на залог и комиссию');s.cash=money(s.cash-margin-fee);s.positions.push({pid:uid(s),id,side,margin,leverage,entry:price(s,id),funding:0});log(s,'Открыта '+side.toUpperCase()+' '+item(id).name+' ×'+leverage+'.');}
export function positionEquity(s,p){const direction=p.side==='long'?1:-1;return p.margin+p.margin*p.leverage*(price(s,p.id)/p.entry-1)*direction-p.funding;}
export function closePosition(s,pid){const i=s.positions.findIndex(p=>p.pid===pid);check(i>=0,'Позиция уже закрыта');const p=s.positions[i],payout=Math.max(0,positionEquity(s,p)-p.margin*p.leverage*.0006);s.cash=money(s.cash+payout);s.positions.splice(i,1);log(s,`Позиция закрыта. На счёт ${money(payout)} CR.`);}
export function makeAuction(s,id='gpu'){check(!s.auction||s.auction.done,'Текущий аукцион ещё идёт');item(id);s.auction={id,bid:Math.round(price(s,id)*.55),bidder:'Зозон',until:s.time+120,escrow:0,done:false,nextNpc:s.time+13};}
export function bidAuction(s){const a=s.auction;check(a&&!a.done&&s.time<a.until,'Аукцион завершён');const next=Math.ceil(a.bid*1.07),extra=next-a.escrow;check(s.cash>=extra,'Не хватает CR на ставку');s.cash=money(s.cash-extra);a.escrow=next;a.bid=next;a.bidder='you';}
export function joinClan(s,name='Контур',mode='create'){check(!s.clan,'Сначала выйди из текущего клана');name=String(name).trim().slice(0,28)||'Контур';s.clan={name,trophies:0,members:mode==='join'?Array.from({length:12},(_,i)=>({id:'npc'+i,name:'Участник '+(i+1),npc:true})):[],wins:0,losses:0};s.clan.members.push({id:'you',name:s.name,npc:false});log(s,'Ты в клане «'+name+'». Кубки и бонус общие для всех участников.');}
export function addClanMember(s){check(s.clan,'Создай клан');check(s.clan.members.length<100,'В клане уже 100 участников');s.clan.members.push({id:uid(s),name:'Игровой участник '+(s.clan.members.length+1),npc:true});}
export function leaveClan(s){check(!s.war,'Дождись окончания войны');s.clan=null;}
export function startWar(s){check(s.clan,'Сначала вступи в клан');check(!s.war&&s.time>=s.warReady,'Команда готовится к следующей войне');check(activeWorkers(s).length>0&&power(s)>=5,'Нужна активная команда с мощностью от 5');check(s.cash>=300,'Взнос за войну: 300 CR');s.cash-=300;const rating=s.clan.trophies,own=(power(s)+Math.sqrt(s.clan.members.length)*2)*(1+(buffs(s).war||0)+(s.profession==='security'?.1:0)),enemy=own*(.85+random(s)*.4)+rating/2000;s.war={until:s.time+60,own,enemy,roll:random(s),opponent:['Чёрный терминал','Пингвины','Пакет потерян','Северный кластер'][Math.floor(random(s)*4)]};s.warReady=s.time+240;log(s,'Началась клановая война с «'+s.war.opponent+'».');}
function marketTick(s){for(const p of CATALOG){const old=s.prices[p.id],noise=(random(s)-.5)*.025,revert=(p.base-old)/p.base*.012,close=Math.max(p.base*.15,old*(1+noise+revert)),spread=.004+random(s)*.008;s.prices[p.id]=money(close);s.history[p.id].push({o:old,c:close,h:Math.max(old,close)*(1+spread),l:Math.min(old,close)*(1-spread)});s.history[p.id]=s.history[p.id].slice(-90);}for(let i=s.orders.length-1;i>=0;i--){const o=s.orders[i],quote=price(s,o.id)*(o.side==='buy'?1.008:.992);if(o.side==='sell'&&quote>=o.limit){s.cash=money(s.cash+o.qty*o.limit*.995);s.orders.splice(i,1);log(s,'Продан лот: '+item(o.id).name);}else if(o.side==='buy'&&quote<=o.limit){s.inventory[o.id]=(s.inventory[o.id]||0)+o.qty;s.cash=money(s.cash+(o.limit-quote)*o.qty*1.005);s.orders.splice(i,1);log(s,'Куплен лот: '+item(o.id).name);}}for(let i=s.positions.length-1;i>=0;i--){const p=s.positions[i];if(positionEquity(s,p)<=p.margin*p.leverage*.005){s.positions.splice(i,1);log(s,'Ликвидация '+item(p.id).name+': залог израсходован.');}}}
export function tickTycoon(s,dt){check(Number.isFinite(dt)&&dt>=0,'Некорректное время');dt=Math.min(dt,3600);s.time+=dt;s.marketClock+=dt;let steps=0;while(s.marketClock>=5&&steps<720){s.marketClock-=5;marketTick(s);steps++;}for(const p of s.positions)p.funding+=p.margin*p.leverage*.0001*dt/3600;const j=s.jobs.find(j=>!j.done);if(j){const c=CASES.find(c=>c.id===j.kind),team=activeWorkers(s);if(team.length){const roleBoost=team.some(w=>w.role===c.role)?1.2:1;j.progress+=dt*Math.max(1,power(s)*.28)*roleBoost*(1+(buffs(s).speed||0));if(j.progress>=c.work){j.done=true;j.reward=Math.round(c.reward*revenueMultiplier(s,c.role));s.cash+=j.reward;s.revenue+=j.reward;s.finished++;log(s,c.name+' завершён: +'+j.reward+' CR.');}}}s.jobs=s.jobs.slice(-30);
 const a=s.auction;if(a&&!a.done){if(s.time>=a.until){a.done=true;if(a.bidder==='you'){s.inventory[a.id]=(s.inventory[a.id]||0)+1;a.escrow=0;log(s,'Аукцион выигран: '+item(a.id).name);}else log(s,'Аукцион завершён. Лот получил игровой соперник.');}else if(s.time>=a.nextNpc){a.nextNpc=s.time+12+random(s)*15;if(a.bid<price(s,a.id)*(.85+random(s)*.3)&&random(s)>.3){if(a.escrow){s.cash+=a.escrow;a.escrow=0;}a.bid=Math.ceil(a.bid*1.06);a.bidder='NPC / '+['Вега','Линк','Пинг'][Math.floor(random(s)*3)];}}}
 if(s.war&&s.time>=s.war.until){const w=s.war,win=w.roll<Math.max(.25,Math.min(.7,w.own/(w.own+w.enemy))),delta=win?Math.round(27+Math.min(12,Math.max(0,w.enemy-w.own))):-24;s.clan.trophies=Math.max(0,s.clan.trophies+delta);if(win){s.clan.wins++;s.cash+=650;}else s.clan.losses++;log(s,`Война ${win?'выиграна':'проиграна'}: ${delta>0?'+':''}${delta} кубков всем участникам${win?', +650 CR':''}.`);awardLoot(s);s.war=null;}
 const compute=hardware(s).power*.008*dt*(1+(buffs(s).compute||0))*revenueMultiplier(s);s.computeCarry=(s.computeCarry||0)+compute;const credit=Math.floor(s.computeCarry*100)/100;s.computeCarry-=credit;s.cash+=credit;s.computeRevenue+=credit;
 s.cash=money(s.cash);
}

export function sellMarket(s,id,qty=1){item(id);check(Number.isInteger(qty)&&qty>0&&qty<=1000,'Количество: от 1 до 1 000');check((s.inventory[id]||0)>=qty,'Недостаточно товара');s.inventory[id]-=qty;const total=money(price(s,id)*.992*qty);s.cash=money(s.cash+total);log(s,'Рыночная продажа: '+item(id).name+' ×'+qty+', +'+total+' CR.');}
